Variables (ww : list Z) (cw : PMR.ctrl).
Hypothesis HWB : PMW.win_bytes M ps ww.
Hypothesis HRM : PMR.rm_match cw M P ps.
(* [comment removed for export] *)
Hypothesis Hcont : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LB' : list (Z * Z)) (cr' : credit) (LBk : list (Z * Z)) (W : list L5.range),
   PML.fp_ok fx' ->
   (exists (ps' : PML.pstate) (code : Z) (g' : PML.ls_state),
      PML.parser_at M' P ps' /\ PML.wf_ps ps' /\ PML.win_ok M' LBo ps' /\ PML.buf_bound ps' B /\ PML.ec_at M' E code /\
      (code <> 0 -> PML.ps_more ps' = false) /\ PML.ls_ok g' M' /\ (g' = g \/ g' = PML.LS2 /\ code <> 0) /\
      LB' = PML.ps_blocks ps' ++ LBo /\ LBk = LBo /\ W = PML.W_par P E /\ PML.pcredit_x L cr' ps' kx bx /\
      (code = 0 /\ PML.ps_more ps' = true /\ In (PML.ps_st ps') [PML.ST_EXPECT_MEMBER_NAME; PML.ST_EXPECT_VALUE] /\
       PML.ps_stack ps' = PML.ps_stack ps /\ PML.ps_level ps' = PML.ps_level ps /\ PML.ps_win ps' = PML.ps_win ps) /\
      SPTW.w3p PMW.FBeginMember cw ww M' P ps ps' ww code) ->
   regs_preserved R R' -> L5C.hpres L LBk sp SCRC W M M' -> model_but_vm model model' -> hi_heap HI LB' cr' M' (m_vmmaps model') ->
   srealizes RSEGS SCFG (@PML.cfg fx' R' r M' model') K.
